        if minutes:
            raise ValueError(f"unsupported fixed offset {tz}")
        if hours == 0:
            return "Etc/UTC"
        return f"Etc/GMT{'-' if sign == '+' else '+'}{hours}"
    if tz in _LINKS:
        return _LINKS[tz]
    if "/" not in tz:
        return tz
    for path in ("/usr/share/zoneinfo/tzdata.zi", "/usr/share/lib/zoneinfo/tzdata.zi"):
        try:
