def _locale(posix: str) -> str:
    base = re.split(r"[.@]", posix.strip())[0]
    tag = base.replace("_", "-")
    parts = tag.split("-")
    language = parts[0].lower()
    if len(parts) > 1 and parts[1]:
        candidate = f"{language}-{parts[1].upper()}"
        if candidate in _SUPPORTED:
